if(typeof window!=='undefined'){document.addEventListener('click',event=>{const button=event.target.closest?.('.edit-custom');if(button){event.preventDefault();openCustomEditor(button.dataset.id)}const backup=event.target.closest?.('#backupNow');if(backup){event.preventDefault();download(`LueckenSprint_yedek_${today()}.json`,'application/json',JSON.stringify(S,null,2))}});document.addEventListener('submit',event=>{if(event.target?.id!=='settingsForm')return;const form=new FormData(event.target),bands=[0,1,2,3].map(i=>Number(form.get(`band${i}`)));S.settings.shortWords=form.get('shortWords')==='on';if(bands.every(n=>Number.isFinite(n)&&n>0&&n<=100)&&bands.every((n,i)=>i===0||n>bands[i-1]))S.settings.bands=bands;else{event.preventDefault();toast('Sonuç bantları 1–100 arasında ve artan olmalıdır.')}} ,true)}
renderSettings=()=>{const z=S.settings,b=z.bands||[60,70,80,90],toggles=[['lenient','Pratikte büyük/küçük harfi hoşgör'],['acceptSS','Pratikte ß yerine ss kabul et'],['hint','İlk harf ipucunu göster'],['shortWords','Gelişmiş: 3 harfli kelimeleri de kes'],['timer','Pratikte süreyi varsayılan aç'],['autoNext','Sonraki boşluğa otomatik geç'],['instantSave','Yanıtları hemen kaydet'],['confirmExam','Denemeyi bitirmeden onay iste']];return `${header('Ayarlar','Çalışmanı sana uyarla.','İlerleme önce bu cihazda kaydedilir; giriş yaptığında otomatik olarak eşitlenir.')}<div class="grid grid-2"><section class="card"><form id="settingsForm"><div class="form-row"><label>Tema</label><select name="theme">${['system','light','dark'].map(x=>`<option value="${x}" ${z.theme===x?'selected':''}>${x==='system'?'Sistem':x==='light'?'Açık':'Koyu'}</option>`).join('')}</select></div><div class="form-row"><label>Yazı boyutu</label><input name="font" type="range" min="14" max="20" value="${z.font}"><small class="label">${z.font}px</small></div><div class="form-row"><label>Günlük hedef (boşluk)</label><input name="dailyTarget" type="number" min="10" max="200" value="${z.dailyTarget}"></div>${toggles.map(([k,l])=>`<label class="toggle" style="margin:12px 0"><input type="checkbox" name="${k}" ${z[k]?'checked':''}> ${l}</label>`).join('')}<h3>Eğitim sonuç bantları</h3><p class="label">Sırasıyla: gelişim gerekli, gelişiyor, hedefe yaklaşıyor, güçlü hedef.</p><div class="grid grid-2">${b.map((value,i)=>`<div class="form-row"><label>${['%60 eşiği','%70 eşiği','%80 eşiği','%90 eşiği'][i]}</label><input name="band${i}" type="number" min="1" max="100" value="${value}"></div>`).join('')}</div><button class="button" style="margin-top:16px">Ayarları kaydet</button></form></section><section class="card"><h2 style="margin-top:0">Veri dışa aktarımı</h2><div class="choice-row"><button class="button-outline" id="exportErrors">Hataları CSV indir</button><button class="button-outline" id="exportExams">Denemeleri CSV indir</button></div><details class="advanced-backup"><summary>Gelişmiş yedekleme</summary><p class="label">JSON yedeğini yalnızca taşımak veya manuel saklamak gerektiğinde kullanın.</p><div class="choice-row">${window.__STANDALONE__?'<button class="button" id="backupNow">Yedek oluştur</button>':''}<button class="button-outline" id="exportJson">JSON yedeğini indir</button></div><div class="form-row" style="margin-top:14px"><label>JSON yedeğini içe aktar</label><input id="importJson" type="file" accept="application/json,.json"></div></details>${window.__STANDALONE__?'<div class="warning" style="margin-top:14px">iOS yerel HTML depolamasını kısıtlayabilir veya temizleyebilir. Düzenli JSON yedeği oluşturun.</div>':''}<hr style="border:0;border-top:1px solid var(--line);margin:23px 0"><button class="button-danger" id="resetData">Tüm yerel ilerlemeyi sıfırla</button></section></div><div id="syncPanelHost"></div>`}
function trainingBand(percent){const thresholds=S.settings.bands||[60,70,80,90];return percent<thresholds[0]?'Belirgin gelişim gerekli':percent<thresholds[1]?'Gelişiyor':percent<thresholds[2]?'Hedefe yaklaşıyor':percent<thresholds[3]?'Güçlü hedef performansı':'Çok güçlü performans'}
renderExamResult=function(r){const latest=S.attempts.at(-1);const rows=(latest?.textScores||[]).map(x=>`<tr><td>${esc(x.title)}</td><td>${x.level}</td><td>${x.correct}/${x.total}</td><td>${x.percent}%</td></tr>`).join('');document.querySelector('#main').innerHTML=`<div class="eyebrow">Tam Deneme</div><h1 class="page-title">Deneme tamamlandı</h1><p class="lead">Eğitim tahmini: ${trainingBand(r.percent)}.</p><section class="card"><div class="result-row"><div><small>Doğru</small><b>${r.correct}</b></div><div><small>Yanlış</small><b>${r.total-r.correct-r.unanswered}</b></div><div><small>Boş</small><b>${r.unanswered}</b></div><div><small>Toplam</small><b>${r.percent}%</b></div></div><div class="warning">Bu seviye tahmini FAU’nun resmî yerleştirme sonucu değildir. Ayarlardaki eğitim bantları kullanılmıştır.</div><div class="table-wrap"><table class="data-table"><tr><th>Metin</th><th>Seviye</th><th>Doğru</th><th>Sonuç</th></tr>${rows}</table></div><div class="exercise-actions"><button class="button-outline" data-go="errors">Hataları tekrar et</button><button class="button" data-go="exam">Yeni deneme</button></div></section>`;bindView()}
renderExamResult=function(r){const last=S.attempts.at(-1),rows=(last?.textScores||[]).map(x=>`<tr><td>${esc(x.title)}</td><td>${x.level}</td><td>${x.correct}/${x.total}</td><td>${x.percent}%</td></tr>`).join('');document.querySelector('#main').innerHTML=`${header('Tam Deneme','Deneme tamamlandı',`Eğitim tahmini: ${trainingBand(r.percent)}.`)}<section class="card"><div class="result-row"><div><small>Doğru</small><b>${r.correct}</b></div><div><small>Yanlış</small><b>${r.total-r.correct-r.unanswered}</b></div><div><small>Boş</small><b>${r.unanswered}</b></div><div><small>Toplam</small><b>${r.percent}%</b></div></div><div class="warning">Bu seviye tahmini FAU’nun resmî yerleştirme sonucu değildir. Ayarlardaki eğitim bantları kullanılmıştır.</div><h3>Metinlere göre sonuç</h3><div class="table-wrap"><table class="data-table"><tr><th>Metin</th><th>Seviye</th><th>Doğru</th><th>Sonuç</th></tr>${rows}</table></div><div class="exercise-actions"><button class="button-outline" data-go="errors">Hataları tekrar et</button><button class="button" data-go="exam">Yeni deneme</button></div></section>`;bindView()}
const ROUTES={home:'#/start',daily:'#/tagestraining',practice:'#/training',exam:'#/pruefung',errors:'#/fehlertraining',custom:'#/eigene-texte',stats:'#/statistik',settings:'#/einstellungen'},ROUTE_VIEWS=Object.fromEntries(Object.entries(ROUTES).map(([view,route])=>[route,view]));
function currentRouteView(){const route=window.location.hash||ROUTES.home;const view=ROUTE_VIEWS[route];if(!view){history.replaceState(null,'',ROUTES.home);return'home'}return view}
function navigate(view){const route=ROUTES[view]||ROUTES.home;if(location.hash===route){render();return}location.hash=route}
function activeExamIsValid(){const e=S.activeExam;if(!e)return false;try{if(!Array.isArray(e.sets)||!e.sets.length)throw new Error('no sets');e.sets=e.sets.map(set=>{const text=findText(set.text?.id)||set.text;if(!text?.text)throw new Error('missing text');const generated=set.generated?.items?.length?set.generated:ctest(text.text,{gaps:20});if(!generated.gapCount)throw new Error('invalid text');return{...set,text,generated,answers:Array.isArray(set.answers)?set.answers.slice(0,generated.gapCount).concat(Array(Math.max(0,generated.gapCount-set.answers.length)).fill('')):Array(generated.gapCount).fill('')}});if(!Number.isInteger(e.current)||e.current<0||e.current>=e.sets.length)e.current=0;if(!Number.isFinite(e.remaining))e.remaining=EXAM_SECONDS;e.remaining=Math.max(0,Math.min(EXAM_SECONDS,e.remaining));return true}catch(error){S.recoveredExams=[...(S.recoveredExams||[]),{at:Date.now(),reason:String(error?.message||'invalid')}];S.activeExam=null;save();console.warn('LückenSprint: ungültige Prüfung wiederhergestellt',error);return false}}
function recoverExamClock(e){const stamp=Number(e.lastUpdated||e.started||Date.now()),passed=Math.max(0,Math.floor((Date.now()-stamp)/1000));if(passed){e.remaining=Math.max(0,e.remaining-passed);e.lastUpdated=Date.now()}return e.remaining}
renderExamStart=()=>`${header('Prüfung','Prüfung starten','Fünf C-Tests, 40 Minuten und eine realistische Prüfungssimulation.')}<div class="grid grid-2"><section class="card"><span class="pill">40 Minuten · 5 Texte</span><h2>Gemischte Prüfung</h2><p class="lead">Die Lösungen werden erst nach der Abgabe angezeigt.</p><button class="button" id="startExam">Prüfung starten</button></section><section class="card"><h3>Hinweis</h3><p class="lead">Diese Einschätzung ist kein offizielles Einstufungsergebnis der FAU.</p></section></div>`;
renderExam=()=>{if(!activeExamIsValid())return S.lastExamResult?renderStoredExamResult():renderExamStart();const e=S.activeExam;if(recoverExamClock(e)<=0){setTimeout(submitExam,0);return'<section class="card empty">Die Prüfungszeit ist abgelaufen. Das Ergebnis wird berechnet …</section>'}const set=e.sets[e.current];if(!set)return renderExamStart();const total=e.sets.reduce((n,s)=>n+s.generated.gapCount,0),done=e.sets.reduce((n,s)=>n+s.answers.filter(Boolean).length,0),answered=set.answers.filter(Boolean).length;return `${header('Prüfung','Laufende Prüfung','Ihre Antworten werden auf diesem Gerät gespeichert.')}<div class="sticky"><section class="card"><div class="exercise-head"><div><span class="pill">Text ${e.current+1} / ${e.sets.length} · ${esc(set.text.level)}</span><div class="exam-tabs">${e.sets.map((s,i)=>`<button class="exam-tab ${i===e.current?'active':''} ${s.answers.some(Boolean)?'complete':''}" data-exam-tab="${i}">${i+1}</button>`).join('')}</div></div><div><span class="timer" id="examTimer">${clock(e.remaining)}</span><br><small class="label">${done}/${total} beantwortet</small></div></div><div class="progressbar"><i style="width:${total?done/total*100:0}%"></i></div></section></div><section class="card" style="margin-top:17px"><h2>${esc(set.text.title)}</h2><article class="ctext" id="examText">${set.generated.html}</article><div class="exercise-actions"><button class="button-outline" id="examPrev" ${e.current===0?'disabled':''}>← Zurück</button><span class="label">Dieser Text: ${answered}/${set.generated.gapCount}</span>${e.current===e.sets.length-1?'<button class="button" id="endExam">Prüfung abgeben</button>':'<button class="button" id="examNext">Weiter →</button>'}</div></section>`};
function renderStoredExamResult(){const r=S.lastExamResult;if(!r)return renderExamStart();return `${header('Prüfung','Letztes Prüfungsergebnis','Diese Einschätzung ist kein offizielles Einstufungsergebnis der FAU.')}<section class="card"><div class="result-row"><div><small>Richtige Antworten</small><b>${r.correct}</b></div><div><small>Falsche Antworten</small><b>${r.incorrect}</b></div><div><small>Nicht beantwortet</small><b>${r.unanswered}</b></div><div><small>Ergebnis</small><b>${r.percent}%</b></div></div>${(r.textScores||[]).map((score,i)=>`<details class="mistake"><summary>Text ${i+1}: ${esc(score.title)} · ${score.correct}/${score.total}</summary>${(r.details||[]).filter(d=>d.text?.title===score.title).map(resultDetail).join('')}</details>`).join('')}<div class="exercise-actions"><button class="button" id="startExam">Neue Prüfung starten</button></div></section>`}
function resultDetail(d){const state=d.correct?'richtig':d.answer?'falsch':'nicht beantwortet';return `<div class="mistake result-detail ${state}"><b>${esc(d.prefix)}${esc(d.missing)}</b><br><span>Ihre Antwort: <em>${esc(d.answer||'—')}</em></span><br><span>Richtige Ergänzung: <strong>${esc(d.missing)}</strong></span><br><span>Vollständiges Wort: <strong>${esc(d.word)}</strong></span><br><span>${esc(sentenceFor(d.text?.text||'',d.word))}</span><br><small>${state}${d.correct?'':` · ${esc(category(d))}`} · ${esc(d.text?.level||'')}</small></div>`}
newExam=()=>{const texts=examTexts(),sets=texts.map(text=>{const generated=ctest(text.text,{gaps:20});return{text,generated,answers:Array(generated.gapCount).fill('')}});S.activeExam={id:uid(),started:Date.now(),lastUpdated:Date.now(),remaining:EXAM_SECONDS,current:0,sets,alerts:[]};save();render()};
startExamTimer=()=>{clearInterval(interval);interval=setInterval(()=>{const e=S.activeExam;if(!e)return clearInterval(interval);recoverExamClock(e);const timer=document.querySelector('#examTimer');if(timer)timer.textContent=clock(e.remaining);if(e.remaining<=0){clearInterval(interval);submitExam()}else if(e.remaining%5===0)save()},1000)};
submitExam=()=>{const e=S.activeExam;if(!e)return;clearInterval(interval);const details=e.sets.flatMap(set=>score(set.generated.items,set.answers,{lenient:false,acceptSS:false}).details.map(d=>({...d,text:set.text}))),total=details.length,correct=details.filter(d=>d.correct).length,unanswered=details.filter(d=>!d.answer).length,incorrect=total-correct-unanswered,elapsed=EXAM_SECONDS-e.remaining,textScores=e.sets.map(set=>{const s=score(set.generated.items,set.answers,{lenient:false,acceptSS:false});return{title:set.text.title,level:set.text.level,correct:s.correct,total:s.total,percent:s.percent}}),result={id:e.id,details,total,correct,incorrect,unanswered,percent:total?Math.round(correct/total*100):0,elapsed,textScores,finishedAt:Date.now()};S.attempts.push({id:e.id,date:today(),mode:'exam',level:'Gemischt',topic:'Gemischt',title:'Prüfung',correct,total,percent:result.percent,time:elapsed,textScores,details});details.filter(d=>!d.correct).forEach(d=>S.errors.push({id:uid(),date:today(),text:d.text.title,level:d.text.level,topic:d.text.topic,word:d.word,prefix:d.prefix,missing:d.missing,answer:d.answer,context:sentenceFor(d.text.text,d.word),category:category(d),mastery:0,updated_at:new Date().toISOString()}));S.lastExamResult=result;S.activeExam=null;save();render()};
renderResult=(a,r)=>{const main=document.querySelector('#main'),avg=Math.round(Math.max(1,(Date.now()-a.started)/1000)/Math.max(1,r.total));main.innerHTML=`${header('Ergebnis','Trainingsergebnis','Alle Lösungen werden direkt nach der Auswertung angezeigt.')}<section class="card"><div class="result-row"><div><small>Anzahl der Lücken</small><b>${r.total}</b></div><div><small>Richtig</small><b>${r.correct}</b></div><div><small>Falsch</small><b>${r.incorrect}</b></div><div><small>Nicht beantwortet</small><b>${r.unanswered}</b></div></div><p class="label">Genauigkeit: ${r.percent}% · Bearbeitungszeit: ${Math.round((Date.now()-a.started)/60000)} Min. · Ø ${avg} Sek./Lücke</p><div class="choice-row"><button class="chip result-filter selected" data-filter="all">Alle</button><button class="chip result-filter" data-filter="wrong">Nur falsche</button><button class="chip result-filter" data-filter="empty">Nur unbeantwortete</button><button class="chip result-filter" data-filter="correct">Nur richtige</button></div><div id="resultDetails">${r.details.map(d=>resultDetail({...d,text:a.text})).join('')}</div><div class="exercise-actions"><button class="button-outline" data-go="errors">Diesen Fehler üben</button><button class="button" data-go="practice">Erneut versuchen</button></div></section>`;document.querySelectorAll('.result-filter').forEach(button=>button.onclick=()=>{document.querySelectorAll('.result-filter').forEach(x=>x.classList.toggle('selected',x===button));document.querySelectorAll('.result-detail').forEach(row=>row.hidden=button.dataset.filter!=='all'&&!row.classList.contains(button.dataset.filter==='wrong'?'falsch':button.dataset.filter==='empty'?'nicht':'richtig'))});bindView()};
render=()=>{clearInterval(interval);const view=currentRouteView(),renderer={home:renderHome,daily:renderDaily,practice:renderPractice,exam:renderExam,errors:renderErrors,custom:renderCustom,stats:renderStats,settings:renderSettings}[view],main=document.querySelector('#main');window.VIEW=view;try{const html=renderer?renderer():renderHome();if(typeof html!=='string'||/^(undefined|null|\[object Object\]|NaN)$/i.test(html.trim()))throw new Error('Ungültige Seitenvorlage');main.innerHTML=html;document.querySelectorAll('.nav-btn').forEach(button=>button.classList.toggle('active',button.dataset.view===view));bindView();if(view==='exam'&&S.activeExam){wireExamGaps();startExamTimer()}window.LueckenSync?.mountSettingsPanel?.()}catch(error){console.error('LückenSprint render error',error);main.innerHTML=`<section class="card warning"><h1>Seite konnte nicht angezeigt werden</h1><p>Ein unerwarteter Fehler ist aufgetreten.</p><button class="button" id="reloadPage">Seite erneut laden</button><button class="button-outline" id="goHome">Zur Startseite</button></section>`;document.querySelector('#reloadPage').onclick=()=>location.reload();document.querySelector('#goHome').onclick=()=>navigate('home')}};
if(typeof window!=='undefined'&&typeof document!=='undefined'){document.addEventListener('click',event=>{const routeButton=event.target.closest?.('[data-view],[data-go]');if(routeButton){const view=routeButton.dataset.view||routeButton.dataset.go;if(ROUTES[view])navigate(view)}},true);window.addEventListener('hashchange',()=>{if(document.readyState!=='loading')render()})}
if(typeof module!=='undefined')module.exports={ctest,score,norm,firstSentenceEnd,DB,setDatabase,getDatabase:()=>DB,restoreCachedDatabase,cacheDatabase,trainingBand,ROUTES,currentRouteView,activeExamIsValid};
function sentenceFor(text,word){return text.split(/(?<=[.!?])\s+/u).find(s=>s.includes(word))||text}
function renderResult(a,r){const avg=Math.round(Math.max(1,(Date.now()-a.started)/1000)/r.total);document.querySelector('#main').innerHTML=`${header('Sonuç','Pratik değerlendirmesi',r.percent>=80?'Çok iyi — güçlü hedef performansı.':'Her yanlış, sonraki pratik için değerli bir işaret.')}
<section class="card"><div class="result-row"><div><small>Doğru</small><b>${r.correct}</b></div><div><small>Yanlış</small><b>${r.incorrect}</b></div><div><small>Boş</small><b>${r.unanswered}</b></div><div><small>Sonuç</small><b>${r.percent}%</b></div></div><p class="label">Süre: ${Math.round((Date.now()-a.started)/60)} dk · Boşluk başına ortalama: ${avg} sn</p><div class="warning">Bu seviye tahmini FAU’nun resmî yerleştirme sonucu değildir.</div><h3>Çözümler ve hata analizi</h3>${r.details.map(d=>`<div class="mistake"><b>${esc(d.prefix)}${esc(d.missing)}</b> ${d.correct?'✓':'— Senin cevabın: '+(esc(d.answer)||'boş')}<br><span class="label">${d.correct?'Doğru.':`Doğru eksik bölüm: <b>${esc(d.missing)}</b> · ${esc(sentenceFor(a.text.text,d.word))} · ${d.correct?'':'Kategori: '+category(d)}`}</span></div>`).join('')}<div class="exercise-actions"><button class="button-outline" data-go="errors">Bu hatayı tekrar çalış</button>${window.MIX&&window.MIX.index<window.MIX.list.length-1?'<button class="button" id="nextMixed">Sonraki metin</button>':'<button class="button" data-go="practice">Yeni pratik</button>'}</div></section>`;bindView();document.querySelector('#nextMixed')?.addEventListener('click',()=>{window.MIX.index++;startPractice(window.MIX.list[window.MIX.index],{gaps:S.settings.gaps,timer:S.settings.timer})})}

/* Current user interface: German-only overrides for the retained compatibility code above. */
function category(item){const w=item.word.toLowerCase(),a=(item.answer||'').toLowerCase();if(w.includes('\u00df')&&a.includes('ss'))return'\u00df oder ss';if(/[\u00e4\u00f6\u00fc]/.test(w)&&!/[\u00e4\u00f6\u00fc]/.test(a))return'Umlaut';if(item.word[0]!==item.word[0].toLowerCase())return'Gro\u00df- und Kleinschreibung';if(/(ung|heit|keit|schaft|tion)$/u.test(w))return'Nomenendung';if(/(en|ern|est|et|te)$/u.test(w))return'Verbform';if(/(ig|lich|isch|bar)$/u.test(w))return'Adjektivendung';if(/(weil|obwohl|deshalb|damit|jedoch)$/u.test(w))return'Konnektor';if(w.includes('-'))return'Zusammengesetztes Wort';return'Rechtschreibung'}
function formatDate(d){return new Intl.DateTimeFormat('de-DE',{day:'numeric',month:'long',year:'numeric'}).format(new Date(`${d}T12:00:00`))}
function phase(){const d=today();if(d<='2026-08-07')return['Phase 1 · Format verstehen','29. Juli – 7. August','L\u00f6sen Sie heute zwei kurze Texte und achten Sie auf Endungen und Kontext.'];if(d<='2026-08-17')return['Phase 2 · Texte unter Zeitdruck','8. – 17. August','Trainieren Sie A2, B1 und B2 gemischt; planen Sie etwa sechs bis sieben Minuten je Text ein.'];if(d<='2026-08-28')return['Phase 3 · Intensives gemischtes Training','18. – 28. August','L\u00f6sen Sie mindestens 60 L\u00fccken und wiederholen Sie schwierige Kategorien.'];if(d<='2026-09-04')return['Phase 4 · Vollst\u00e4ndige Pr\u00fcfungen','29. August – 4. September','Konzentrieren Sie sich heute auf eine Pr\u00fcfung oder das Fehlertraining.'];return['Phase 5 · Leichte Wiederholung','5. – 6. September','L\u00f6sen Sie einen kurzen gemischten Test; vermeiden Sie anstrengendes Training.']}
function modal(title,text,onOK,label='Best\u00e4tigen'){const m=document.querySelector('#modal');m.innerHTML=`<div class="modal"><h2>${esc(title)}</h2><p>${esc(text)}</p><div class="modal-actions"><button class="button-outline" id="modalNo">Abbrechen</button><button class="button" id="modalYes">${esc(label)}</button></div></div>`;m.classList.remove('hidden');m.querySelector('#modalNo').onclick=()=>m.classList.add('hidden');m.querySelector('#modalYes').onclick=()=>{m.classList.add('hidden');onOK()}}
function ctest(text,{gaps=20,every=2,shortWords=false,hint=false}={}){const start=firstSentenceEnd(text),head=text.slice(0,start),tail=text.slice(start),token=/https?:\/\/\S+|www\.\S+|\b(?:[A-Za-z\u00c4\u00d6\u00dc\u00e4\u00f6\u00fc\u00df]\.){2,}|\b\d+(?:[.,]\d+)?\b|[A-Za-z\u00c4\u00d6\u00dc\u00e4\u00f6\u00fc\u00df]+(?:['’][A-Za-z\u00c4\u00d6\u00dc\u00e4\u00f6\u00fc\u00df]+)?(?:-[A-Za-z\u00c4\u00d6\u00dc\u00e4\u00f6\u00fc\u00df]+)*/gu;let last=0,eligible=0,used=0,html=esc(head),items=[],m;while((m=token.exec(tail))){html+=esc(tail.slice(last,m.index));const word=m[0],pure=/^[A-Za-z\u00c4\u00d6\u00dc\u00e4\u00f6\u00fc\u00df]+$/u.test(word),ok=pure&&(shortWords?word.length>=3:word.length>=4);if(ok)eligible++;if(ok&&eligible%every===0&&used<gaps){const cut=Math.floor(word.length/2),prefix=word.slice(0,cut),missing=word.slice(cut),id=`gap-${used}`;html+=`<span class="word-gap">${esc(prefix)}<input aria-label="Wort, das mit ${esc(prefix)} beginnt" placeholder="${hint?esc(missing[0]):''}" class="gap" style="--gap-ch:${missing.length}" id="${id}" data-gap="${used}" data-word="${esc(word)}" data-prefix="${esc(prefix)}" autocomplete="off" autocapitalize="none" spellcheck="false"></span><span class="punct"></span>`;items.push({id,word,prefix,missing,index:m.index});used++}else html+=esc(word);last=m.index+word.length}html+=esc(tail.slice(last));return{html,items,gapCount:items.length,head}}
function renderHome(){const s=attemptStats(),p=phase(),last=S.attempts.slice(-5).reverse(),dailyGaps=S.attempts.filter(x=>x.date===today()).reduce((n,x)=>n+x.total,0);return `${header('FAU-Einstufungsvorbereitung','Nutzen Sie jede L\u00fccke als Hinweis.','Ihr pers\u00f6nlicher, offline nutzbarer C-Test-Trainer.')}<section class="hero"><div><div class="eyebrow">7. September 2026 · Pr\u00fcfungstag</div><h1>Ziel: im C-Test mindestens B1.2, idealerweise B2.1 erreichen.</h1><p>Dieses Werkzeug bewertet nicht Ihre Sprechkompetenz. Es trainiert Tempo, Kontext und korrekte Schreibung im C-Test-Format.</p><button class="button" data-go="practice">Schnelles Training starten</button></div><div class="countdown"><strong>${dayDiff('2026-09-07')}</strong><span>Tage verbleiben</span><div class="progressbar" style="margin-top:15px"><i style="width:${Math.min(100,Math.max(0,100-dayDiff('2026-09-07')/40*100))}%"></i></div></div></section><div class="grid grid-3" style="margin-top:18px">${metric('Abgeschlossene Trainings',s.exercises)}${metric('Beantwortete L\u00fccken',s.gaps)}${metric('Durchschnittliche Genauigkeit',s.accuracy+'%')}${metric('Pr\u00fcfungen',s.exams)}${metric('Bestes Pr\u00fcfungsergebnis',s.best?s.best+'%':'—')}${metric('Heutige L\u00fccken',dailyGaps+'/'+S.settings.dailyTarget)}</div><div class="section-heading"><h2>Heutiger Plan</h2><span>${formatDate(today())}</span></div><section class="card phase"><h3>${p[0]}</h3><p><b>${p[1]}</b> · ${p[2]}</p><div style="margin-top:14px"><button class="button-outline" id="taskDone">${S.tasks[today()]?'✓ Heute erledigt':'Heutige Aufgabe erledigen'}</button></div></section><div class="grid grid-2" style="margin-top:18px"><section class="card"><h3 style="margin-top:0">Letzte Ergebnisse</h3>${last.length?`<div class="table-wrap"><table class="data-table"><tr><th>Datum</th><th>Art</th><th>Niveau</th><th>Ergebnis</th></tr>${last.map(x=>`<tr><td>${x.date}</td><td>${x.mode==='exam'?'Pr\u00fcfung':'Training'}</td><td>${x.level}</td><td>${x.percent}%</td></tr>`).join('')}</table></div>`:'<p class="empty">Nach Ihrem ersten Training erscheinen die Ergebnisse hier.</p>'}</section><section class="card"><h3 style="margin-top:0">T\u00e4gliche Serie</h3><strong style="font-size:35px">${streak()} Tage</strong><p class="lead" style="font-size:13px;margin:8px 0">Abgeschlossene Tage sind im Kalender gr\u00fcn markiert. Halten Sie die Serie mit mindestens einem Training pro Tag aufrecht.</p><button class="button-outline" data-go="daily">Zum Tagestraining</button></section></div>`}
function renderDaily(){const d=today(),text=ALL[(Array.from(d).reduce((a,c)=>a+c.charCodeAt(0),0))%ALL.length],done=S.daily[d]?.completed;return `${header('Tagestraining','Der kurze C-Test f\u00fcr heute','F\u00fcr jedes Datum wird dieselbe \u00dcbung ausgew\u00e4hlt. Ihr Fortschritt bleibt auf diesem Ger\u00e4t gespeichert.')}<section class="card"><div class="exercise-head"><div><span class="pill">${text.level} · ${esc(text.topic)}</span><h2>${esc(text.title)}</h2><p class="lead" style="font-size:14px;margin:0">20 L\u00fccken · Tagesserie: ${streak()} Tage</p></div>${done?'<span class="success">✓ Heute abgeschlossen</span>':'<button class="button" id="dailyStart">Tagestraining starten</button>'}</div></section><div class="section-heading"><h2>Aktivit\u00e4tskalender</h2><span>Letzte 35 Tage</span></div><section class="card"><div class="calendar">${Array.from({length:35},(_,i)=>{const x=new Date();x.setDate(x.getDate()-34+i);const k=x.toISOString().slice(0,10),hit=S.daily[k]?.completed||S.tasks[k];return`<div class="day ${hit?'done':''}" title="${k}" aria-label="${k}${hit?', abgeschlossen':''}">${x.getDate()}</div>`}).join('')}</div></section>`}
function topicOptions(){return `<option value="all">Alle Themen</option>${TOPICS.map(x=>`<option value="${esc(x[0])}">${esc(x[0])}</option>`).join('')}`}
function renderPractice(){return `${header('Training','Erg\u00e4nzen Sie L\u00fccken in Ihrem Tempo.','Im Trainingsmodus werden die L\u00f6sungen nach der Abgabe angezeigt. Die tolerante Bewertung l\u00e4sst sich in den Einstellungen \u00e4ndern.')}<div class="grid grid-2"><section class="card"><h2 style="margin-top:0">Schnelles Training</h2><form id="practiceForm"><div class="form-row"><label>Niveau</label><select name="level"><option value="mixed">Gemischt (A1–C1)</option>${optionsLevels()}</select></div><div class="form-row"><label>Thema</label><select name="topic">${topicOptions()}</select></div><div class="form-row"><label>Anzahl der L\u00fccken</label><div class="choice-row">${[10,15,20].map(n=>`<button type="button" class="chip ${n===S.settings.gaps?'selected':''}" data-gaps="${n}">${n} L\u00fccken</button>`).join('')}</div></div><label class="toggle"><input name="timer" type="checkbox" ${S.settings.timer?'checked':''}> Zeit messen</label><div style="margin-top:20px"><button class="button">Training starten</button></div></form></section><section class="card"><h2 style="margin-top:0">Gemischtes und adaptives Training</h2><p class="lead" style="font-size:14px">Die adaptive Auswahl priorisiert oft fehlerhafte Kategorien und bisher noch nicht bearbeitete Texte.</p><div class="form-row"><label>Anzahl der Texte</label><select id="mixedCount"><option value="2">2 Texte</option><option value="3">3 Texte</option><option value="5">5 Texte</option></select></div><button class="button-outline" id="mixedStart">Gemischtes Set starten</button><button class="button-outline" id="adaptiveStart" style="margin-left:8px">Adaptives Training starten</button><hr style="border:0;border-top:1px solid var(--line);margin:23px 0"><h3>Training nach Niveau</h3><div class="choice-row">${LEVELS.map(x=>`<button class="chip level-start" data-level="${x}">${x}</button>`).join('')}</div></section></div>`}
function startPractice(text,{gaps=S.settings.gaps,timer=false,daily=false,custom=false}={}){const generated=ctest(text.text,{gaps,hint:S.settings.hint,shortWords:S.settings.shortWords});if(!generated.gapCount){toast('Dieser Text enth\u00e4lt nicht genug geeignete W\u00f6rter.');return}window.ACTIVE={mode:'practice',text,generated,answers:Array(generated.gapCount).fill(''),started:Date.now(),timer:timer?Math.max(60,generated.gapCount*25):0,daily,custom};renderExercise()}
function renderExercise(){const a=window.ACTIVE,g=a.generated;document.querySelector('#main').innerHTML=`<div class="sticky"><div class="card"><div class="exercise-head"><div><span class="pill">${a.text.level} · ${esc(a.text.topic)}</span><h2 style="margin:7px 0 0">${esc(a.text.title)}</h2></div>${a.timer?`<span class="timer" id="timer">${clock(a.timer)}</span>`:'<span class="pill">Freies Training</span>'}</div><div class="progressbar"><i id="answerProgress" style="width:0"></i></div><small class="label" id="answerCount">0 / ${g.gapCount} L\u00fccken beantwortet</small></div></div><section class="card" style="margin-top:17px"><article class="ctext" id="exerciseText">${g.html}</article><div class="exercise-actions"><span class="label">Hinweis: Mit Tab oder Eingabe zur n\u00e4chsten L\u00fccke wechseln.</span><button class="button" id="submitPractice">Antworten pr\u00fcfen</button></div></section>`;wireGaps(a);if(a.timer)beginTimer()}
function updateAnswerProgress(a){const n=a.answers.filter(Boolean).length,p=document.querySelector('#answerProgress'),c=document.querySelector('#answerCount');if(p)p.style.width=`${n/a.generated.gapCount*100}%`;if(c)c.textContent=`${n} / ${a.generated.gapCount} L\u00fccken beantwortet`}
function beginTimer(){clearInterval(interval);interval=setInterval(()=>{const a=window.ACTIVE;if(!a)return clearInterval(interval);a.timer--;const t=document.querySelector('#timer');if(t)t.textContent=clock(a.timer);if(a.timer<=0){clearInterval(interval);toast('Die Zeit ist abgelaufen. Die Antworten werden gepr\u00fcft.');submitPractice()}},1000)}
function renderErrors(){const errs=S.errors.filter(x=>x.mastery<3).slice().reverse();return `${header('Fehlertraining','Festigen Sie schwierige L\u00fccken.','Ein Wort gilt nach drei richtigen Wiederholungen als gefestigt.')}<section class="card">${errs.length?`<p class="lead" style="font-size:14px">${errs.length} aktive Fehler${errs.length===1?'':'eintr\u00e4ge'}. Erg\u00e4nzen Sie jeweils den fehlenden Teil.</p>${errs.map(e=>`<div class="mistake"><span class="pill">${esc(e.level)} · ${esc(e.category)}</span><p style="margin:10px 0">${esc(e.context.replace(e.word,e.prefix+'_____'))}</p><b>${esc(e.prefix)}</b><input class="gap review-input" data-error="${esc(e.id)}" aria-label="Fehlenden Wortteil erg\u00e4nzen"><button class="button-outline check-error" data-error="${esc(e.id)}">Antwort pr\u00fcfen</button><small class="label" style="margin-left:8px">Gefestigt: ${e.mastery}/3</small></div>`).join('')}`:'<div class="empty">Keine aktiven Fehler. Neue Fehler aus dem Training erscheinen hier.</div>'}</section>`}
function checkError(id){const e=S.errors.find(x=>x.id===id),inp=document.querySelector(`.review-input[data-error="${id}"]`);if(!e||!inp)return;const ok=norm(inp.value,{lenient:true,acceptSS:S.settings.acceptSS})===norm(e.missing,{lenient:true,acceptSS:S.settings.acceptSS});if(ok){e.mastery++;inp.classList.add('correct');toast(e.mastery>=3?'Dieser Fehler ist gefestigt.':'Richtig! Eine Wiederholung wurde gespeichert.')}else{e.mastery=0;inp.classList.add('wrong');toast(`Richtige Erg\u00e4nzung: ${e.missing}`)}save();setTimeout(render,600)}
function renderCustom(){const saved=S.custom||[];return `${header('Eigene Texte','Erstellen Sie aus Ihrem eigenen Text einen C-Test.','Sie k\u00f6nnen den Text im Browser speichern, bearbeiten oder l\u00f6schen.')}<div class="grid grid-2"><section class="card"><form id="customForm"><div class="form-row"><label>Titel</label><input name="title" required placeholder="z. B. Mein Studienalltag"></div><div class="grid grid-2"><div class="form-row"><label>Niveau</label><select name="level">${optionsLevels()}</select></div><div class="form-row"><label>Thema</label><input name="topic" value="Eigener Text"></div></div><div class="form-row"><label>Deutscher Text</label><textarea name="text" required placeholder="Der erste Satz bleibt vollst\u00e4ndig. In den folgenden S\u00e4tzen werden L\u00fccken automatisch erstellt."></textarea></div><div class="grid grid-2"><div class="form-row"><label>L\u00fccken</label><select name="gaps"><option>10</option><option>15</option><option selected>20</option><option>25</option></select></div><div class="form-row"><label>Abstand</label><select name="every"><option value="2">Jedes zweite geeignete Wort</option><option value="3">Jedes dritte geeignete Wort</option></select></div></div><button class="button" name="action" value="start">Vorschau und Training</button><button class="button-outline" name="action" value="save" style="margin-left:8px">Lokal speichern</button></form></section><section class="card"><h2 style="margin-top:0">Gespeicherte Texte</h2>${saved.length?saved.map(x=>`<div class="mistake"><b>${esc(x.title)}</b> <span class="pill">${x.level}</span><br><small class="label">${esc(x.topic)} · ${x.text.split(/\s+/).length} W\u00f6rter</small><div style="margin-top:9px"><button class="chip use-custom" data-id="${x.id}">Trainieren</button><button class="chip edit-custom" data-id="${x.id}">Bearbeiten</button><button class="chip delete-custom" data-id="${x.id}">L\u00f6schen</button></div></div>`).join(''):'<div class="empty">Noch keine eigenen Texte gespeichert.</div>'}</section></div>`}
function openCustomEditor(id){const item=S.custom.find(x=>x.id===id);if(!item)return;const box=document.querySelector('#modal');box.innerHTML=`<div class="modal"><h2>Text bearbeiten</h2><div class="form-row"><label>Titel</label><input id="editTitle" value="${esc(item.title)}"></div><div class="form-row"><label>Thema</label><input id="editTopic" value="${esc(item.topic)}"></div><div class="form-row"><label>Niveau</label><select id="editLevel">${LEVELS.map(x=>`<option ${x===item.level?'selected':''}>${x}</option>`).join('')}</select></div><div class="form-row"><label>Deutscher Text</label><textarea id="editText">${esc(item.text)}</textarea></div><div class="modal-actions"><button class="button-outline" id="modalNo">Abbrechen</button><button class="button" id="saveCustomEdit">\u00c4nderungen speichern</button></div></div>`;box.classList.remove('hidden');box.querySelector('#modalNo').onclick=()=>box.classList.add('hidden');box.querySelector('#saveCustomEdit').onclick=()=>{const title=box.querySelector('#editTitle').value.trim(),text=box.querySelector('#editText').value.trim();if(!title||!text){toast('Titel und Text sind erforderlich.');return}item.title=title;item.topic=box.querySelector('#editTopic').value.trim()||'Eigener Text';item.level=box.querySelector('#editLevel').value;item.text=text;save();box.classList.add('hidden');render()}}
function renderStats(){const a=S.attempts,byLevel=LEVELS.map(l=>{const x=a.filter(q=>q.level===l);const n=x.reduce((z,q)=>z+q.total,0),ok=x.reduce((z,q)=>z+q.correct,0);return{l,p:n?Math.round(ok/n*100):0,n}}),byTopic={};a.forEach(x=>{if(!byTopic[x.topic])byTopic[x.topic]=[0,0];byTopic[x.topic][0]+=x.correct;byTopic[x.topic][1]+=x.total});const weak=[...S.errors].filter(x=>x.mastery<3).reduce((o,x)=>(o[x.category]=(o[x.category]||0)+1,o),{}),s=attemptStats();return `${header('Statistik','Machen Sie Ihren Fortschritt sichtbar.','Es werden nur die auf diesem Ger\u00e4t gespeicherten Trainings berechnet.')}<div class="grid grid-3">${metric('Gesamtgenauigkeit',s.accuracy+'%')}${metric('St\u00e4rkstes Niveau',byLevel.filter(x=>x.n).sort((a,b)=>b.p-a.p)[0]?.l||'—')}${metric('Aktive Fehler',S.errors.filter(x=>x.mastery<3).length)}</div><div class="grid grid-2" style="margin-top:18px"><section class="card"><h3 style="margin-top:0">Genauigkeit nach Niveau</h3>${byLevel.map(x=>`<div style="margin:13px 0"><div style="display:flex;justify-content:space-between;font-size:13px"><b>${x.l}</b><span>${x.n?x.p+'%':'Noch keine Daten'}</span></div><div class="progressbar"><i style="width:${x.p}%"></i></div></div>`).join('')}</section><section class="card"><h3 style="margin-top:0">Schwierige Bereiche</h3>${Object.keys(weak).length?Object.entries(weak).sort((a,b)=>b[1]-a[1]).map(([k,v])=>`<div class="mistake"><b>${esc(k)}</b><span style="float:right">${v} Fehler</span></div>`).join(''):'<div class="empty">Sobald Fehler vorliegen, erscheinen ihre Kategorien hier.</div>'}</section></div><div class="grid grid-2" style="margin-top:18px"><section class="card"><h3 style="margin-top:0">W\u00f6chentliche Aktivit\u00e4t</h3><div class="bar-chart">${Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);const k=d.toISOString().slice(0,10),n=a.filter(x=>x.date===k).reduce((z,x)=>z+x.total,0);return`<div class="bar" style="height:${Math.max(7,Math.min(100,n/S.settings.dailyTarget*100))}%" title="${n} L\u00fccken"><span>${d.getDate()}</span></div>`}).join('')}</div></section><section class="card"><h3 style="margin-top:0">Leistung nach Thema</h3>${Object.keys(byTopic).length?Object.entries(byTopic).map(([k,[ok,n]])=>`<div class="mistake">${esc(k)}<span style="float:right">${Math.round(ok/n*100)}%</span></div>`).join(''):'<div class="empty">Schlie\u00dfen Sie ein Training ab; die Themenverteilung erscheint dann hier.</div>'}</section></div>`}
function trainingBand(percent){const thresholds=S.settings.bands||[60,70,80,90];return percent<thresholds[0]?'Deutlicher \u00dcbungsbedarf':percent<thresholds[1]?'In Entwicklung':percent<thresholds[2]?'Nahe am Ziel':percent<thresholds[3]?'Starke Zielerreichung':'Sehr starke Leistung'}
function renderSettings(){const z=S.settings,b=z.bands||[60,70,80,90],toggles=[['lenient','Gro\u00df- und Kleinschreibung im Training tolerant bewerten'],['acceptSS','ss statt \u00df im Training akzeptieren'],['hint','Hinweis mit dem ersten Buchstaben anzeigen'],['shortWords','Erweitert: auch W\u00f6rter mit drei Buchstaben k\u00fcrzen'],['timer','Zeitmessung im Training standardm\u00e4\u00dfig aktivieren'],['autoNext','Automatisch zur n\u00e4chsten L\u00fccke wechseln'],['instantSave','Antworten sofort speichern'],['confirmExam','Vor Abgabe der Pr\u00fcfung nachfragen']];return `${header('Einstellungen','Passen Sie das Training an.','Fortschritte werden zuerst auf diesem Ger\u00e4t gespeichert und nach der Anmeldung automatisch synchronisiert.')}<div class="grid grid-2"><section class="card"><form id="settingsForm"><div class="form-row"><label>Darstellung</label><select name="theme">${['system','light','dark'].map(x=>`<option value="${x}" ${z.theme===x?'selected':''}>${x==='system'?'System':x==='light'?'Hell':'Dunkel'}</option>`).join('')}</select></div><div class="form-row"><label>Schriftgr\u00f6\u00dfe</label><input name="font" type="range" min="14" max="20" value="${z.font}"><small class="label">${z.font}px</small></div><div class="form-row"><label>Tagesziel (L\u00fccken)</label><input name="dailyTarget" type="number" min="10" max="200" value="${z.dailyTarget}"></div>${toggles.map(([k,l])=>`<label class="toggle" style="margin:12px 0"><input type="checkbox" name="${k}" ${z[k]?'checked':''}> ${l}</label>`).join('')}<h3>Bewertungsb\u00e4nder f\u00fcr das Training</h3><p class="label">Reihenfolge: \u00dcbungsbedarf, Entwicklung, nahe am Ziel, starke Zielerreichung.</p><div class="grid grid-2">${b.map((value,i)=>`<div class="form-row"><label>${['60-%-Schwelle','70-%-Schwelle','80-%-Schwelle','90-%-Schwelle'][i]}</label><input name="band${i}" type="number" min="1" max="100" value="${value}"></div>`).join('')}</div><button class="button" style="margin-top:16px">Einstellungen speichern</button></form></section><section class="card"><h2 style="margin-top:0">Datenexport</h2><div class="choice-row"><button class="button-outline" id="exportErrors">Fehler als CSV herunterladen</button><button class="button-outline" id="exportExams">Pr\u00fcfungen als CSV herunterladen</button></div><details class="advanced-backup"><summary>Erweiterte Sicherung</summary><p class="label">Verwenden Sie die JSON-Sicherung nur zum \u00dcbertragen oder manuellen Aufbewahren.</p><div class="choice-row">${window.__STANDALONE__?'<button class="button" id="backupNow">Sicherung erstellen</button>':''}<button class="button-outline" id="exportJson">JSON-Sicherung herunterladen</button></div><div class="form-row" style="margin-top:14px"><label>JSON-Sicherung importieren</label><input id="importJson" type="file" accept="application/json,.json"></div></details>${window.__STANDALONE__?'<div class="warning" style="margin-top:14px">iOS kann die Speicherung lokaler HTML-Dateien einschr\u00e4nken oder l\u00f6schen. Erstellen Sie regelm\u00e4\u00dfig eine JSON-Sicherung.</div>':''}<hr style="border:0;border-top:1px solid var(--line);margin:23px 0"><button class="button-danger" id="resetData">Gesamten lokalen Fortschritt zur\u00fccksetzen</button></section></div><div id="syncPanelHost"></div>`}
function startMixed(count,adaptive){const errors=S.errors.filter(x=>x.mastery<3);let candidates=adaptive&&errors.length?ALL.filter(x=>errors.some(e=>e.topic===x.topic||e.level===x.level)):ALL,list=[],used=new Set();while(list.length<count&&candidates.length){const x=candidates[(Date.now()+list.length*43)%candidates.length];if(!used.has(x.id)){list.push(x);used.add(x.id)}else candidates=candidates.filter(q=>q.id!==x.id)}if(!list.length){toast('Es sind keine Texte verf\u00fcgbar.');return}window.MIX={list,index:0};startPractice(list[0],{gaps:S.settings.gaps,timer:S.settings.timer});toast(`Gemischtes Set mit ${count} Texten gestartet. Der erste Text ist ge\u00f6ffnet.`)}
function setupStandaloneBackup(){if(!window.__STANDALONE__)return;const b=document.createElement('button');b.className='backup-float';b.type='button';b.textContent='Sicherung erstellen';b.title='iOS kann lokale Daten l\u00f6schen. Bewahren Sie eine JSON-Sicherung auf.';b.onclick=()=>download(`LueckenSprint_Sicherung_${today()}.json`,'application/json',JSON.stringify(S,null,2));document.body.appendChild(b);setTimeout(()=>toast('Im lokalen HTML-Modus kann iOS Daten l\u00f6schen. Erstellen Sie regelm\u00e4\u00dfig eine JSON-Sicherung.'),700)}
function renderResult(a,r){const main=document.querySelector('#main'),avg=Math.round(Math.max(1,(Date.now()-a.started)/1000)/Math.max(1,r.total));main.innerHTML=`${header('Ergebnis','Trainingsergebnis','Alle L\u00f6sungen werden direkt nach der Auswertung angezeigt.')}<section class="card"><div class="result-row"><div><small>Anzahl der L\u00fccken</small><b>${r.total}</b></div><div><small>Richtig</small><b>${r.correct}</b></div><div><small>Falsch</small><b>${r.incorrect}</b></div><div><small>Nicht beantwortet</small><b>${r.unanswered}</b></div></div><p class="label">Genauigkeit: ${r.percent}% · Bearbeitungszeit: ${Math.round((Date.now()-a.started)/60000)} Min. · Ø ${avg} Sek./L\u00fccke</p><div class="choice-row"><button class="chip result-filter selected" data-filter="all">Alle</button><button class="chip result-filter" data-filter="wrong">Nur falsche</button><button class="chip result-filter" data-filter="empty">Nur unbeantwortete</button><button class="chip result-filter" data-filter="correct">Nur richtige</button></div><div id="resultDetails">${r.details.map(d=>resultDetail({...d,text:a.text})).join('')}</div><div class="exercise-actions"><button class="button-outline" data-go="errors">Fehlertraining \u00f6ffnen</button><button class="button" data-go="practice">Erneut trainieren</button></div></section>`;document.querySelectorAll('.result-filter').forEach(button=>button.onclick=()=>{document.querySelectorAll('.result-filter').forEach(x=>x.classList.toggle('selected',x===button));document.querySelectorAll('.result-detail').forEach(row=>row.hidden=button.dataset.filter!=='all'&&!row.classList.contains(button.dataset.filter==='wrong'?'falsch':button.dataset.filter==='empty'?'nicht':'richtig'))});bindView()}
function bindView(){const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];$$('[data-go]').forEach(b=>b.onclick=()=>{navigate(b.dataset.go);scrollTo(0,0)});$('#taskDone')&&($('#taskDone').onclick=()=>{S.tasks[today()]=true;save();render()});$('#dailyStart')&&($('#dailyStart').onclick=()=>startPractice(ALL[(Array.from(today()).reduce((a,c)=>a+c.charCodeAt(0),0))%ALL.length],{gaps:20,daily:true}));$$('[data-gaps]').forEach(b=>b.onclick=()=>{$$('[data-gaps]').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');S.settings.gaps=+b.dataset.gaps;save()});$('#practiceForm')&&($('#practiceForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);startPractice(choose(f.get('level'),f.get('topic')),{gaps:S.settings.gaps,timer:f.get('timer')==='on'})});$$('.level-start').forEach(b=>b.onclick=()=>startPractice(choose(b.dataset.level),{gaps:S.settings.gaps,timer:S.settings.timer}));$('#mixedStart')&&($('#mixedStart').onclick=()=>startMixed(+$('#mixedCount').value,false));$('#adaptiveStart')&&($('#adaptiveStart').onclick=()=>startMixed(+$('#mixedCount').value,true));$('#submitPractice')&&($('#submitPractice').onclick=submitPractice);$('#startExam')&&($('#startExam').onclick=newExam);$$('[data-exam-tab]').forEach(b=>b.onclick=()=>{S.activeExam.current=+b.dataset.examTab;save();render()});$('#examPrev')&&($('#examPrev').onclick=()=>{S.activeExam.current--;save();render()});$('#examNext')&&($('#examNext').onclick=()=>{S.activeExam.current++;save();render()});$('#endExam')&&($('#endExam').onclick=()=>{const go=()=>submitExam();S.settings.confirmExam?modal('Pr\u00fcfung abgeben?','Nach der Abgabe k\u00f6nnen Antworten nicht mehr ge\u00e4ndert werden.',go,'Pr\u00fcfung abgeben'):go()});$$('.check-error').forEach(b=>b.onclick=()=>checkError(b.dataset.error));$('#customForm')&&($('#customForm').onclick=e=>{const btn=e.target.closest('button[name=action]');if(!btn)return;e.preventDefault();const f=new FormData(e.currentTarget),obj={id:'custom-'+uid(),title:f.get('title'),level:f.get('level'),topic:f.get('topic'),text:f.get('text'),difficulty:3,readingTime:2,grammarTags:['Eigener Text'],vocabularyTags:['Eigener Text']};if(!obj.title||!obj.text)return toast('Titel und deutscher Text sind erforderlich.');if(btn.value==='save'){S.custom.push(obj);save();toast('Text wurde lokal gespeichert.');render()}else{const made=ctest(obj.text,{gaps:+f.get('gaps'),every:+f.get('every')});if(!made.gapCount)return toast('Verwenden Sie mindestens zwei S\u00e4tze und ausreichend lange W\u00f6rter.');window.ACTIVE={mode:'practice',text:obj,generated:made,answers:Array(made.gapCount).fill(''),started:Date.now(),timer:0,custom:true};renderExercise()}});$$('.use-custom').forEach(b=>b.onclick=()=>startPractice(findText(b.dataset.id),{gaps:S.settings.gaps}));$$('.edit-custom').forEach(b=>b.onclick=()=>openCustomEditor(b.dataset.id));$$('.delete-custom').forEach(b=>b.onclick=()=>modal('Text l\u00f6schen?','Dieser lokale Text wird gel\u00f6scht.',()=>{S.custom=S.custom.filter(x=>x.id!==b.dataset.id);save();render()},'L\u00f6schen'));$('#settingsForm')&&($('#settingsForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),bands=[0,1,2,3].map(i=>Number(f.get(`band${i}`)));if(!bands.every(n=>Number.isFinite(n)&&n>0&&n<=100)||!bands.every((n,i)=>i===0||n>bands[i-1])){toast('Die Bewertungsb\u00e4nder m\u00fcssen zwischen 1 und 100 liegen und aufsteigend sein.');return}for(const k of ['theme','font','dailyTarget'])S.settings[k]=k==='font'||k==='dailyTarget'?+f.get(k):f.get(k);for(const k of ['lenient','acceptSS','hint','shortWords','timer','autoNext','instantSave','confirmExam'])S.settings[k]=f.get(k)==='on';S.settings.bands=bands;save();toast('Einstellungen gespeichert.');render()});$('#backupNow')&&($('#backupNow').onclick=()=>download(`LueckenSprint_Sicherung_${today()}.json`,'application/json',JSON.stringify(S,null,2)));$('#exportJson')&&($('#exportJson').onclick=()=>download(`lueckensprint-${today()}.json`,'application/json',JSON.stringify(S,null,2)));$('#exportErrors')&&($('#exportErrors').onclick=()=>download('lueckensprint-fehler.csv','text/csv;charset=utf-8',csv([['Datum','Text','Niveau','Wort','Antwort','Richtig','Kategorie'],...S.errors.map(x=>[x.date,x.text,x.level,x.word,x.answer,x.missing,x.category])])));$('#exportExams')&&($('#exportExams').onclick=()=>download('lueckensprint-pruefungen.csv','text/csv;charset=utf-8',csv([['Datum','Ergebnis','Richtig','Gesamt','Zeit (Sek.)'],...S.attempts.filter(x=>x.mode==='exam').map(x=>[x.date,x.percent,x.correct,x.total,x.time])])));$('#importJson')&&($('#importJson').onchange=e=>{const file=e.target.files[0];if(!file)return;const r=new FileReader();r.onload=()=>{try{mergeImport(JSON.parse(r.result));toast('Sicherung wurde erfolgreich zusammengef\u00fchrt.');render()}catch{toast('Ung\u00fcltige Sicherungsdatei.')}};r.readAsText(file)});$('#resetData')&&($('#resetData').onclick=()=>modal('Gesamten Fortschritt zur\u00fccksetzen?','Dadurch werden lokale Ergebnisse, Fehler und eigene Texte entfernt.',()=>{S=clone(DEFAULT);save();render()},'Alles zur\u00fccksetzen'))}
if(typeof module!=='undefined')Object.assign(module.exports,{ctest,trainingBand});

/* Resilient examination state machine.  `remaining_ms` is authoritative for
   learning mode; `deadline_at` is authoritative for the strict simulation. */
const EXAM_SCHEMA_VERSION=2,EXAM_STATES=new Set(['not_started','running','paused','submitted','expired','corrupted']);
function examNow(){return Date.now()}
function normalizeExamState(exam){if(!exam||typeof exam!=='object')return null;try{exam.schema_version=EXAM_SCHEMA_VERSION;exam.mode=exam.mode==='strict'?'strict':'learning';exam.status=EXAM_STATES.has(exam.status)?exam.status:(exam.mode==='strict'?'running':'paused');exam.current=Math.max(0,Number(exam.current)||0);exam.current_gap_index=Math.max(0,Number(exam.current_gap_index)||0);exam.started_at=Number(exam.started_at||exam.started||examNow());exam.last_updated_at=Number(exam.last_updated_at||exam.lastUpdated||examNow());exam.accumulated_pause_ms=Math.max(0,Number(exam.accumulated_pause_ms)||0);if(!Number.isFinite(exam.remaining_ms))exam.remaining_ms=Math.max(0,Number(exam.remaining||EXAM_SECONDS)*1000);if(exam.mode==='strict'){exam.deadline_at=Number(exam.deadline_at||exam.deadlineAt||examNow()+exam.remaining_ms);exam.remaining_ms=Math.max(0,exam.deadline_at-examNow());if(!exam.remaining_ms&&exam.status!=='submitted')exam.status='expired'}else{exam.deadline_at=null;exam.remaining_ms=Math.max(0,exam.remaining_ms);if(exam.status==='running'&&!Number.isFinite(exam.timer_started_at))exam.timer_started_at=examNow()}exam.sets=(exam.sets||[]).map(set=>({...set,answers:Array.isArray(set.answers)?set.answers:[],answer_updated_at:Array.isArray(set.answer_updated_at)?set.answer_updated_at:[]}));return exam}catch{return null}}
function examRemainingMs(exam,at=examNow()){if(!exam)return 0;if(exam.mode==='strict')return Math.max(0,Number(exam.deadline_at||0)-at);if(exam.status!=='running')return Math.max(0,Number(exam.remaining_ms)||0);return Math.max(0,(Number(exam.remaining_ms)||0)-(at-Number(exam.timer_started_at||at)))}
function persistExamClock(exam,at=examNow()){if(!exam)return;exam.remaining_ms=examRemainingMs(exam,at);if(exam.mode==='learning'&&exam.status==='running')exam.timer_started_at=at;exam.remaining=Math.ceil(exam.remaining_ms/1000);exam.last_updated_at=at;exam.lastUpdated=at}
function pauseLearningExam(reason='manual'){const exam=S.activeExam;if(!exam||exam.mode!=='learning'||exam.status!=='running')return false;const at=examNow();persistExamClock(exam,at);exam.status='paused';exam.paused_at=at;exam.pause_reason=reason;exam.timer_started_at=null;save();clearInterval(interval);return true}
function resumeLearningExam(){const exam=S.activeExam;if(!exam||exam.mode!=='learning'||exam.status!=='paused')return false;exam.status='running';exam.paused_at=null;exam.timer_started_at=examNow();exam.last_updated_at=exam.timer_started_at;save();render();return true}
function activeExamIsValid(){const exam=normalizeExamState(S.activeExam);if(!exam)return false;try{if(!Array.isArray(exam.sets)||!exam.sets.length)throw new Error('missing sets');exam.sets=exam.sets.map(set=>{const text=findText(set.text?.id)||set.text;if(!text?.text)throw new Error('missing text');const generated=set.generated?.items?.length?set.generated:ctest(text.text,{gaps:20});if(!generated.gapCount)throw new Error('invalid text');const answers=Array.from({length:generated.gapCount},(_,i)=>String(set.answers?.[i]||''));return{...set,text,generated,answers,answer_updated_at:Array.from({length:generated.gapCount},(_,i)=>Number(set.answer_updated_at?.[i])||exam.last_updated_at)}});if(exam.current>=exam.sets.length)exam.current=0;if(exam.mode==='strict'&&examRemainingMs(exam)<=0&&exam.status!=='submitted')exam.status='expired';S.activeExam=exam;return true}catch(error){S.recoveredExams=[...(S.recoveredExams||[]),{id:exam.id||uid(),at:examNow(),reason:'corrupted exam',exam}];S.activeExam=null;save();console.warn('LückenSprint: beschädigte Prüfung archiviert',error);return false}}
function newExam(mode='learning'){const profile=typeof document!=='undefined'?document.querySelector('#examProfile')?.value||'Ausgewogen':'Ausgewogen',texts=examTexts(),at=examNow(),sets=texts.map(text=>{const generated=ctest(text.text,{gaps:20});return{text,generated,answers:Array(generated.gapCount).fill(''),answer_updated_at:Array(generated.gapCount).fill(at)}});S.activeExam={schema_version:EXAM_SCHEMA_VERSION,id:uid(),profile,mode:mode==='strict'?'strict':'learning',status:'running',started_at:at,last_updated_at:at,started:at,lastUpdated:at,deadline_at:mode==='strict'?at+EXAM_SECONDS*1000:null,remaining_ms:EXAM_SECONDS*1000,remaining:EXAM_SECONDS,timer_started_at:at,paused_at:null,accumulated_pause_ms:0,current:0,current_gap_index:0,route:ROUTES.exam,sets,alerts:[]};navigate('exam');save();render()}
function clockMs(ms){const total=Math.max(0,Math.ceil(ms/1000));return clock(total)}
function renderExamStart(){return `${header('Prüfung','Prüfung starten','Wählen Sie einen Modus. Die Ergebnisse sind keine offizielle FAU-Einstufung.')}<section class="card" style="margin-bottom:18px"><div class="form-row"><label>Prüfungsprofil</label><select id="examProfile"><option>Ausgewogen</option><option>B1.2-Ziel</option><option>B2.1-Ziel</option><option>Anspruchsvoll</option><option>Zufällige Mischung</option></select></div></section><div class="grid grid-2"><section class="card"><span class="pill">40 Minuten · 5 Texte</span><h2>Lernmodus</h2><p class="lead">Sie können pausieren. Beim Verlassen der Anwendung wird die Prüfung automatisch pausiert.</p><button class="button" data-start-exam="learning">Lernmodus starten</button></section><section class="card"><span class="pill">Strenge Simulation</span><h2>Prüfungssimulation</h2><p class="lead">Die Zeit läuft im Hintergrund weiter. Diese Simulation kann nicht pausiert werden.</p><button class="button-outline" data-start-exam="strict">Prüfungssimulation starten</button></section></div>`}
function pausedExamOverlay(exam){return `<div class="exam-pause-overlay" role="dialog" aria-modal="true" aria-label="Prüfung pausiert"><section class="card"><span class="pill">Prüfung pausiert</span><h2>Die Prüfung ist angehalten</h2><p>Noch ${clockMs(examRemainingMs(exam))} · Text ${exam.current+1} von ${exam.sets.length}</p><button class="button" id="resumeExam">Fortsetzen</button><button class="button-outline" id="finishPausedExam">Prüfung beenden</button></section></div>`}
function renderExam(){if(!activeExamIsValid())return S.lastExamResult?renderStoredExamResult():renderExamStart();const exam=S.activeExam;if(exam.status==='expired'){setTimeout(()=>submitExam('expired'),0);return'<section class="card empty">Die Prüfungszeit ist abgelaufen. Das Ergebnis wird berechnet …</section>'}if(exam.status==='submitted')return renderStoredExamResult();const set=exam.sets[exam.current],total=exam.sets.reduce((n,s)=>n+s.generated.gapCount,0),done=exam.sets.reduce((n,s)=>n+s.answers.filter(Boolean).length,0),paused=exam.status==='paused';return `${header('Prüfung',exam.mode==='strict'?'Prüfungssimulation':'Lernmodus',exam.mode==='strict'?'Die Prüfung läuft im Hintergrund weiter.':'Beim Verlassen der Anwendung wird die Prüfung automatisch pausiert.')}<div class="sticky"><section class="card"><div class="exercise-head"><div><span class="pill">Text ${exam.current+1} / ${exam.sets.length} · ${esc(set.text.level)}</span><div class="exam-tabs">${exam.sets.map((s,i)=>`<button class="exam-tab ${i===exam.current?'active':''} ${s.answers.some(Boolean)?'complete':''}" data-exam-tab="${i}" ${paused?'disabled':''}>${i+1}</button>`).join('')}</div></div><div><span class="timer" id="examTimer">${clockMs(examRemainingMs(exam))}</span><br><small class="label">${done}/${total} beantwortet</small></div></div><div class="progressbar"><i style="width:${total?done/total*100:0}%"></i></div></section></div><section class="card exam-workspace" style="margin-top:17px"><h2>${esc(set.text.title)}</h2><article class="ctext" id="examText" ${paused?'aria-hidden="true"':''}>${set.generated.html}</article><div class="exercise-actions"><button class="button-outline" id="examPrev" ${exam.current===0||paused?'disabled':''}>← Zurück</button><span class="label">Dieser Text: ${set.answers.filter(Boolean).length}/${set.generated.gapCount}</span>${exam.current===exam.sets.length-1?`<button class="button" id="endExam" ${paused?'disabled':''}>Prüfung abgeben</button>`:`<button class="button" id="examNext" ${paused?'disabled':''}>Weiter →</button>`}${exam.mode==='learning'&&!paused?'<button class="button-outline" id="pauseExam">Pause</button>':''}</div>${paused?pausedExamOverlay(exam):''}</section>`}
function wireExamGaps(){const exam=S.activeExam;if(!exam||exam.status!=='running')return;const set=exam.sets[exam.current],inputs=[...document.querySelectorAll('.gap')];inputs.forEach((el,i)=>{el.value=set.answers[i]||'';el.addEventListener('input',()=>{set.answers[i]=el.value;set.answer_updated_at[i]=examNow();exam.current_gap_index=i;exam.last_focused_gap_id=el.id;persistExamClock(exam);save();});el.addEventListener('keydown',event=>{if(event.key==='Enter'){event.preventDefault();(inputs[i+1]||document.querySelector('#examNext')||document.querySelector('#endExam')).focus()}});el.addEventListener('focus',()=>{exam.current_gap_index=i;exam.last_focused_gap_id=el.id;setTimeout(()=>el.scrollIntoView({block:'center',behavior:'smooth'}),50)});});const focus=document.getElementById(exam.last_focused_gap_id||'');if(focus)setTimeout(()=>focus.focus(),0)}
function startExamTimer(){clearInterval(interval);const exam=S.activeExam;if(!exam||exam.status!=='running')return;interval=setInterval(()=>{const current=S.activeExam;if(!current||current.status!=='running')return clearInterval(interval);persistExamClock(current);const timer=document.querySelector('#examTimer');if(timer)timer.textContent=clockMs(current.remaining_ms);if(current.remaining_ms<=0){current.status='expired';save();clearInterval(interval);submitExam('expired')}else if(Math.floor(current.remaining_ms/1000)%5===0)save()},250)}
