function finalizeEmpiricalMetric(current){const ordered=[...current.responseTimes].sort((a,b)=>a-b),middle=Math.floor(ordered.length/2);current.averageResponseTime=Math.round(current.responseTimes.reduce((sum,value)=>sum+value,0)/current.responseTimes.length);current.medianResponseTime=ordered.length%2?ordered[middle]:Math.round((ordered[middle-1]+ordered[middle])/2);current.accuracy=Number((current.correctAttempts/Math.max(1,current.totalResponses)).toFixed(3));current.empiricalDifficulty=current.totalAttempts<20?null:Number((100-current.accuracy*100).toFixed(1));current.discriminationEstimate=current.totalAttempts<50?null:Number((current.accuracy-.5).toFixed(3));return current}
