function renderTargetedTraining(){const errors=(S.errors||[]).filter(error=>error.mastery<3),groups=['Wortebene','Satzebene','Textebene'].map(level=>[level,errors.filter(error=>error.processLevel===level)]);return `${header('Gezieltes C-Test-Training','Trainieren Sie echte C-Test-Rekonstruktionsmuster.','Die Kategorien stammen ausschließlich aus Ihren C-Test-Fehlern.')}<div class="grid grid-3">${groups.map(([level,rows])=>`<section class="card"><span class="pill">${level}</span><h2>${rows.length}</h2><p class="label">${rows.length?'Aktive C-Test-Fehler':'Keine offenen Fehler'}</p><button class="button-outline targeted-start" data-process="${level}" ${rows.length?'':'disabled'}>${level} trainieren</button></section>`).join('')}</div><section class="card" style="margin-top:18px"><h2>Meine häufigsten C-Test-Fehler</h2>${errors.length?errors.slice(0,8).map(error=>`<div class="mistake"><b>${esc(error.completeCorrectWord||error.word)}</b> · ${esc(error.processLevel||'Legacy')}<br><span class="label">${esc(error.shortExplanationGerman||'Dieser Fehler wird aus einem C-Test-Kontext wiederholt.')}</span><br><button class="chip targeted-error" data-error-id="${error.id}">Ähnliche C-Test-Lücke üben</button></div>`).join(''):'<div class="empty">Nach C-Test-Fehlern erscheinen hier passende Wiederholungen.</div>'}</section>`}
