function showEnglishHelp(trigger){if(!englishHelpEnabled(S.settings))return;const entry=englishHelpEntry(trigger?.dataset.englishHelp);if(!entry)return;let panel=document.querySelector('#englishHelpPanel');if(!panel){panel=document.body.appendChild(Object.assign(document.createElement('section'),{id:'englishHelpPanel',className:'english-help-panel',role:'tooltip',hidden:true}));}panel.innerHTML=`<strong>${esc(entry.de)}</strong><span>${esc(entry.en)}</span>`;panel.dataset.key=trigger.dataset.englishHelp;document.querySelectorAll('.english-help-trigger').forEach(button=>button.setAttribute('aria-expanded',String(button===trigger)));trigger.setAttribute('aria-describedby','englishHelpPanel');positionEnglishHelp(trigger,panel)}
function helpify(element,key,inline=false){if(!englishHelpEnabled(S.settings)||!element||element.querySelector?.('.english-help-trigger'))return;const entry=englishHelpEntry(key);if(!entry)return;element.classList.add('has-english-help');element.insertAdjacentHTML('beforeend',englishHelpButton(key));if(inline){const subtitle=document.createElement('small');subtitle.className='english-help-inline';subtitle.textContent=entry.en;element.insertAdjacentElement('afterend',subtitle)}}
