const renderExerciseWithDirectSubmit=renderExercise;renderExercise=function(){renderExerciseWithDirectSubmit();const button=document.querySelector('#submitPractice');if(!button||button.dataset.directSubmitBound)return;button.type='button';button.dataset.directSubmitBound='true';button.addEventListener('click',event=>{event.preventDefault();submitPractice()},{once:true})};

/* CONTEXTUAL_CTEST_EXPLANATIONS: only real, checked C-Test gaps can open an explanation. */
const EXPLANATION_CATEGORIES=Object.freeze({
  wordEnding:{label:'Wortendungen',english:'The visible beginning has to be completed with the exact ending of this word.'},
  articleCase:{label:'Artikel oder Kasussignal',english:'The form is signalled by the word group in this sentence.'},
  verbForm:{label:'Verbformen',english:'The verb form has to fit the sentence and its time reference.'},
  adjectiveEnding:{label:'Adjektivendungen',english:'The ending belongs to the adjective form used in this sentence.'},
  preposition:{label:'Präpositionen',english:'This preposition is the word used at this exact position in the sentence.'},
  conjunction:{label:'Konnektoren',english:'This connector links the two parts of the sentence.'},
  pronounReference:{label:'Pronomenbezug',english:'The pronoun refers to information in the surrounding text.'},
  compoundWord:{label:'Zusammengesetzte Wörter',english:'The missing letters complete one compound word, not two separate words.'},
  sentenceContext:{label:'Satzstellung',english:'You need the complete sentence, including what comes after the gap.'},
  widerTextContext:{label:'Textzusammenhang',english:'The clue is in the surrounding sentences, so read beyond the gap.'}
});
let RESULT_EXPLANATIONS=new Map();
const explanationWord=error=>String(error?.completeCorrectWord||error?.word||'');
const explanationMissing=error=>String(error?.correctCompletion||error?.missing||'');
const explanationPrefix=error=>String(error?.visiblePrefix||error?.prefix||'');
function canExplainGap(error){return Boolean(error&&!error.correct&&error.gapId&&explanationWord(error)&&explanationMissing(error)&&(error.completeSentence||error.context));}
function contextualCategory(error){
  if(!canExplainGap(error))return null;
  const word=explanationWord(error).toLocaleLowerCase('de-DE'),features=error.diagnosticFeatures||[],sentence=String(error.completeSentence||error.context||'');
  if(features.includes('compound_reconstruction')||word.includes('-'))return 'compoundWord';
  if(error.processLevel==='Textebene'||error.requiredContextType==='mehrere Sätze')return 'widerTextContext';
  if(error.processLevel==='Satzebene'||error.requiredContextType==='vollständiger Satz')return 'sentenceContext';
  if(/^(weil|obwohl|denn|dass|damit|deshalb|jedoch)$/u.test(word))return 'conjunction';
  if(/^(mit|nach|bei|von|für|durch|ohne|gegen|über|unter|zwischen)$/u.test(word))return 'preposition';
  if(/^(einen|einem|einer|eines|keinen|keinem|keiner|diesem|diesen|dieser)$/u.test(word))return 'articleCase';
  if(/^(dieser|diese|dieses|ihm|ihnen|daran|dabei|dadurch)$/u.test(word)&&features.includes('cross_sentence_reference'))return 'pronounReference';
  if(/(ig|lich|isch|bar|en)$/u.test(word)&&/(ig|lich|isch|bar)$/u.test(word))return 'adjectiveEnding';
  if(/(en|ern|est|et|te|ten)$/u.test(word)&&/\b(ist|sind|hat|haben|wird|werden|war|waren|kann|muss|soll)\b/iu.test(sentence))return 'verbForm';
  if(explanationPrefix(error)&&explanationMissing(error))return 'wordEnding';
  return null;
}
function contextualExplanation(error,englishEnabled=englishHelpEnabled(S.settings)){
  const category=contextualCategory(error);if(!category)return null;
  const meta=EXPLANATION_CATEGORIES[category],word=explanationWord(error),missing=explanationMissing(error),prefix=explanationPrefix(error),sentence=String(error.completeSentence||error.context||''),wide=error.processLevel==='Textebene'?[error.previousSentence,error.completeSentence,error.followingSentence].filter(Boolean).join(' '):'';
  const processReason=category==='widerTextContext'?'Die Form wird erst klar, wenn Sie die Sätze davor oder danach mitlesen.':category==='sentenceContext'?'Die Satzteile nach der Lücke liefern den nötigen Hinweis.':`Die sichtbare Hälfte „${prefix}“ muss genau mit „${missing}“ ergänzt werden.`;
  return {category,label:meta.label,word,missing,prefix,sentence,widerContext:wide,why:`Das korrekte Wort lautet „${word}“. ${processReason}`,clue:`Im Originalsatz steht: „${sentence}“`,english:englishEnabled?`The answer is “${word}”. ${meta.english}`:'',example:`Beispiel: ${prefix} + ${missing} = ${word}.`,similar:similarPracticeGaps(error)};
}
function similarPracticeGaps(error){return similarGaps(error).slice(0,3).map(gap=>({gapId:gap.gapId,textId:gap.textId,word:gap.completeWord||gap.originalWord,prefix:gap.visiblePrefix,missing:gap.correctCompletion,sentence:gap.completeSentence,level:gap.cefrLevel}));}
function updateExplanationTopics(){const counts={};for(const error of S.errors||[]){if(error.mastery>=3)continue;const category=contextualCategory(error);if(category){error.explanationCategory=category;counts[category]=(counts[category]||0)+1;}}S.explanationTopics=counts;return counts;}
function explanationButton(error,source='error'){if(!canExplainGap(error))return '';return `<button type="button" class="chip contextual-explain" data-contextual-explain="${esc(source)}" data-explanation-id="${esc(error.id||error.gapId)}">Thema erklären</button>${englishHelpEnabled(S.settings)?'<small class="contextual-english-help">See a short explanation of the pattern behind this C-Test gap.</small>':''}<div class="contextual-explanation-host"></div>`}
function contextualExplanationMarkup(error){const explanation=contextualExplanation(error);if(!explanation)return '<p class="label">Für diese Lücke liegen keine belastbaren C-Test-Metadaten vor.</p>';return `<section class="contextual-explanation" aria-live="polite"><span class="pill">${esc(explanation.label)}</span><h3>Warum war diese Lücke schwierig?</h3><p>${esc(explanation.why)}</p><p><b>Vollständiges Wort:</b> ${esc(explanation.word)}<br><b>Vollständiger Satz:</b> ${esc(explanation.sentence)}</p>${explanation.widerContext?`<p><b>Weiterer Textzusammenhang:</b> ${esc(explanation.widerContext)}</p>`:''}<h3>Woran konnte man die Lösung erkennen?</h3><p>${esc(explanation.clue)}</p>${explanation.english?`<h3>Kurze Erklärung auf Englisch</h3><p class="contextual-english">${esc(explanation.english)}</p>`:''}<h3>Einfaches Beispiel</h3><p>${esc(explanation.example)}</p><h3>Ähnliche C-Test-Lücken üben</h3>${explanation.similar.length?`<ul class="contextual-similar">${explanation.similar.map(gap=>`<li><b>${esc(gap.prefix)}${esc(gap.missing)}</b> · ${esc(gap.sentence)} <button type="button" class="chip" data-similar-gap-text="${esc(gap.textId)}">Üben</button></li>`).join('')}</ul>`:'<p class="label">Im geladenen Korpus gibt es derzeit keine ausreichend ähnliche Lücke.</p>'}</section>`}
function resultExplanationError(detail,text){if(detail?.correct||!text)return null;const made=ctest(text.text,{gaps:20,level:text.level,textId:text.id}),item=made.items.find(candidate=>candidate.id===detail.id||(candidate.word===detail.word&&candidate.prefix===detail.prefix));if(!item?.diagnostic)return null;return {...item.diagnostic,id:`result-${text.id}-${item.id}`,answer:detail.answer,correct:false,missing:item.missing,word:item.word,prefix:item.prefix,completeCorrectWord:item.word,correctCompletion:item.missing,completeSentence:item.diagnostic.completeSentence,previousSentence:item.diagnostic.previousSentence,followingSentence:item.diagnostic.followingSentence};}
const storeResultWithContextualExplanations=storeResult;storeResult=function(active,result){const previous=S.errors.length;storeResultWithContextualExplanations(active,result);S.errors.slice(previous).forEach(error=>{const category=contextualCategory(error);if(category)error.explanationCategory=category;});updateExplanationTopics();save()};
const submitExamWithContextualExplanations=submitExam;submitExam=function(...args){const previous=S.errors.length,result=submitExamWithContextualExplanations(...args);S.errors.slice(previous).forEach(error=>{const category=contextualCategory(error);if(category)error.explanationCategory=category;});updateExplanationTopics();save();return result};
const renderResultWithContextualExplanations=renderResult;renderResult=function(active,result){RESULT_EXPLANATIONS=new Map();const details=(result.details||[]).map((detail,index)=>{const error=resultExplanationError(detail,active.text);if(error)RESULT_EXPLANATIONS.set(error.id,error);const state=detail.correct?'richtig':detail.answer?'falsch':'nicht beantwortet';return `<article class="mistake result-detail ${state}"><b>${esc(detail.prefix)}${esc(detail.missing)}</b><p>Ihre Antwort: <em>${esc(detail.answer||'—')}</em><br>Richtige Ergänzung: <strong>${esc(detail.missing)}</strong><br>Vollständiges Wort: <strong>${esc(detail.word)}</strong></p>${error?explanationButton(error,'result'):''}</article>`}).join('');document.querySelector('#main').innerHTML=`${header('Ergebnis','Trainingsergebnis','Erklärungen werden nur für falsch oder offen gelassene C-Test-Lücken angezeigt.')}<section class="card"><div class="result-row"><div><small>Richtig</small><b>${result.correct}</b></div><div><small>Falsch</small><b>${result.incorrect}</b></div><div><small>Nicht beantwortet</small><b>${result.unanswered}</b></div><div><small>Ergebnis</small><b>${result.percent}%</b></div></div><h2>Lösungen und C-Test-Erklärungen</h2><div id="resultDetails">${details}</div><div class="exercise-actions"><button class="button-outline" data-go="errors">Fehlertraining öffnen</button><button class="button" data-go="practice">Neues Training</button></div></section>`;bindView()};
const renderErrorsWithContextualExplanations=renderErrors;renderErrors=function(){const errors=(S.errors||[]).filter(error=>error.mastery<3).slice().reverse(),base=renderErrorsWithContextualExplanations();let index=0;return base.replace(/<\/article>/gu,()=>`${explanationButton(errors[index++],'error')}</article>`)};
const renderTargetedWithContextualExplanations=renderTargetedTraining;renderTargetedTraining=function(){const errors=(S.errors||[]).filter(error=>error.mastery<3).slice(0,8);return `${renderTargetedWithContextualExplanations()}<section class="card contextual-targeted"><h2>Thema erklären</h2><p class="label">Die Hinweise entstehen ausschließlich aus Ihren gespeicherten C-Test-Fehlern.</p>${errors.length?errors.map(error=>`<div class="mistake"><b>${esc(error.completeCorrectWord||error.word)}</b>${explanationButton(error,'error')}</div>`).join(''):'<div class="empty">Nach der Auswertung einer falschen oder offenen Lücke erscheinen hier Erklärungen.</div>'}</section>`};
const renderStatsWithContextualExplanations=renderStats;renderStats=function(){const topics=updateExplanationTopics(),rows=Object.entries(topics).sort((left,right)=>right[1]-left[1]);return `${renderStatsWithContextualExplanations()}<section class="card contextual-topics"><h2>Schwierige Themen</h2>${rows.length?rows.map(([category,count])=>`<div class="mistake"><b>${esc(EXPLANATION_CATEGORIES[category]?.label||category)}</b><span>${count} offene C-Test-Lücke${count===1?'':'n'}</span></div>`).join(''):'<div class="empty">Nach falsch oder offen beantworteten C-Test-Lücken erscheinen hier nur Ihre tatsächlichen Schwierigkeiten.</div>'}</section>`};
if(typeof window!=='undefined'){document.addEventListener('click',event=>{const explain=event.target.closest?.('[data-contextual-explain]');if(explain){const error=explain.dataset.contextualExplain==='result'?RESULT_EXPLANATIONS.get(explain.dataset.explanationId):(S.errors||[]).find(item=>item.id===explain.dataset.explanationId);const host=explain.parentElement?.querySelector('.contextual-explanation-host');if(error&&host){host.innerHTML=contextualExplanationMarkup(error);const category=contextualCategory(error);if(category){error.explanationCategory=category;updateExplanationTopics();save();}return;} }const similar=event.target.closest?.('[data-similar-gap-text]');if(similar){const text=findText(similar.dataset.similarGapText);if(text)startPractice(text,{gaps:Math.min(10,S.settings.gaps),timer:false});}})}
if(typeof module!=='undefined')Object.assign(module.exports,{EXPLANATION_CATEGORIES,canExplainGap,contextualCategory,contextualExplanation,similarPracticeGaps,resultExplanationError});
